// With the `tauri` feature, generate the Tauri permission files for the plugin's commands (permissions/autogenerated).
const COMMANDS: &[&str] = &["drives", "disc", "rip", "cancel", "backend_info", "probe"];
fn main() {
    #[cfg(feature = "tauri")]
    tauri_plugin::Builder::new(COMMANDS).build();
    let _ = COMMANDS;
}
